   );
end entity egress_interface_blocks;

architecture rtl of egress_interface_blocks is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   type state_type is (IDLE, ACTIVE);
   signal state_reg, state_next : state_type;
   signal done_reg, done_next : std_logic;
   signal error_reg, error_next : std_logic;
   signal status_reg, status_next : std_logic_vector(7 downto 0);
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk, rst)
   begin
      if rst = '1' then
         state_reg <= IDLE;
         done_reg <= '0';
         error_reg <= '0';
         status_reg <= (others => '0');
      elsif rising_edge(clk) then
         state_reg <= state_next;
         done_reg <= done_next;
         error_reg <= error_next;
         status_reg <= status_next;
      end if;
   end process;

   process(state_reg, enable_i, data_i)
   begin
      state_next <= state_reg;
      done_next <= '0';
      error_next <= '0';
      status_next <= (others => '0');

      case state_reg is
         when IDLE =>
            if enable_i = '1' then
               state_next <= ACTIVE;
            end if;
         when ACTIVE =>
            state_next <= IDLE;
            done_next <= '1';
            status_next <= data_i;
         when others =>
            null;
      end case;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

