entity packet_tracker is
  port (
    clk : in std_logic;
    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity packet_tracker;

architecture rtl of packet_tracker is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   type state_type is (IDLE, TRACKING, COMPLETE);
   signal current_state : state_type := IDLE;
   signal byte_counter : unsigned(7 downto 0) := (others => '0');
   signal packet_valid : std_logic := '0';
   signal packet_boundary : std_logic := '0';
   signal route_select : unsigned(3 downto 0) := (others => '0');
   signal status_reg : unsigned(3 downto 0) := (others => '0');
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk)
   begin
      if rising_edge(clk) then
         if rst = '1' then
            current_state <= IDLE;
            byte_counter <= (others => '0');
            packet_valid <= '0';
            packet_boundary <= '0';
            route_select <= (others => '0');
            status_reg <= (others => '0');
         elsif enable_i = '1' then
            case current_state is
               when IDLE =>
                  current_state <= TRACKING;
                  byte_counter <= (others => '0');
                  packet_valid <= '1';
                  packet_boundary <= '0';
                  route_select <= (others => '0');
                  status_reg <= (others => '0');
               when TRACKING =>
                  byte_counter <= byte_counter + 1;
                  packet_valid <= '1';
                  packet_boundary <= '0';
                  status_reg <= (others => '0');
                  if byte_counter = 7 then
                     current_state <= COMPLETE;
                     packet_boundary <= '1';
                     status_reg <= (others => '0');
                  end if;
               when COMPLETE =>
                  current_state <= IDLE;
                  packet_valid <= '0';
                  packet_boundary <= '0';
                  status_reg <= (others => '0');
            end case;
         end if;
      end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

