architecture rtl of packet_tracker is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
  type pkt_state_t is (IDLE, ACTIVE);
  signal pkt_state : pkt_state_t := IDLE;
  signal byte_cnt : unsigned(7 downto 0) := (others => '0');
  signal route_id : std_logic_vector(3 downto 0) := (others => '0');
  signal pkt_status : std_logic_vector(7 downto 0) := (others => '0');
  signal is_active : std_logic := '0';
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
  process(clk, rst)
  begin
    if rst = '1' then
      pkt_state <= IDLE;
      byte_cnt <= (others => '0');
      route_id <= (others => '0');
      pkt_status <= (others => '0');
      is_active <= '0';
    elsif rising_edge(clk) then
      if enable_i = '1' then
        case pkt_state is
          when IDLE =>
            pkt_state <= ACTIVE;
            is_active <= '1';
            byte_cnt <= (others => '0');
            route_id <= data_i(7 downto 4);
            pkt_status <= data_i;
          when ACTIVE =>
            byte_cnt <= byte_cnt + 1;
            pkt_status <= std_logic_vector(byte_cnt(7 downto 0));
        end case;
      else
        if pkt_state = ACTIVE then
          pkt_state <= IDLE;
          is_active <= '0';
          byte_cnt <= (others => '0');
        end if;
      end if;
    end if;
  end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

