entity alu is
  port (
    clk : in std_logic;
    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity alu;

architecture rtl of alu is
   signal alu_result : std_logic_vector(7 downto 0);
   signal zero_flag  : std_logic;
   signal carry_flag : std_logic;
   signal overflow_flag : std_logic;
begin
   process(clk, rst)
     variable op_code : std_logic_vector(3 downto 0);
     variable operand : unsigned(7 downto 0);
   begin
     if rst = '1' then
       alu_result <= (others => '0');
       zero_flag  <= '0';
       carry_flag <= '0';
       overflow_flag <= '0';
     elsif rising_edge(clk) then
       if enable_i = '1' then
         op_code := data_i(7 downto 4);
         operand := resize(unsigned(data_i(3 downto 0)), 8);
         case op_code is
           when "0000" => -- ADD
             alu_result <= std_logic_vector(operand + operand);
             carry_flag <= '0';
             zero_flag  <= '1' when (operand + operand) = 0 else '0';
             overflow_flag <= '0';
           when "0001" => -- SUB
             alu_result <= std_logic_vector(operand - operand);
             carry_flag <= '0';
             zero_flag  <= '1' when (operand - operand) = 0 else '0';
             overflow_flag <= '0';
           when "0010" => -- AND
             alu_result <= std_logic_vector(operand and operand);
