entity spi_master is
  port (
    clk : in std_logic;
    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity spi_master;

architecture rtl of spi_master is
  type state_type is (IDLE, STAGE1, STAGE2, STAGE3, DONE);
  signal state_reg : state_type := IDLE;
  signal cnt_reg : integer range 0 to 4 := 0;
  signal done_reg : std_logic := '0';
  signal error_reg : std_logic := '0';
  signal status_reg : std_logic_vector(7 downto 0) := "00000000";
begin
  process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        state_reg <= IDLE;
        cnt_reg <= 0;
        done_reg <= '0';
        error_reg <= '0';
        status_reg <= "00000000";
      else
        case state_reg is
          when IDLE =>
            if enable_i = '1' then
              state_reg <= STAGE1;
              cnt_reg <= 1;
            end if;
          when STAGE1 =>
            state_reg <= STAGE2;
            cnt_reg <= 2;
          when STAGE2 =>
            state_reg <= STAGE3;
            cnt_reg <= 3;
          when STAGE3 =>
            state_reg <= DONE;
            cnt_reg <= 4;
          when DONE =>
            done_reg <= '1';
            error_reg <= '0';
            status_reg <= "00000001";
            state_reg <= IDLE;
            cnt_reg <= 0;
          when others =>
            state_reg <= IDLE;
        end case;
      end if;
    end if;
  end process;
end architecture rtl;

library ieee;
use ieee.std_logic_1164.all;
use ieee.numeric_std.all;
use work.uart_spi_protocol_bridge_pkg.all;

entity spi_master is
  port (
    clk : in std_logic;
    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity spi_master;

architecture rtl of spi_master is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
  type state_type is (IDLE, SHIFT, DONE);
  signal state_reg, state_next : state_type := IDLE;
  signal tx_cnt : integer range 0 to 3 := 0;
  signal data_reg : std_logic_vector(7 downto 0) := (others => '0');
  signal sclk_reg : std_logic := '0';
  signal cs_reg : std_logic := '1';
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
  process(clk)
  begin
    if rising_edge(clk) then
      if rst = '1' then
        state_reg <= IDLE;
        tx_cnt <= 0;
        data_reg <= (others => '0');
        sclk_reg <= '0';
        cs_reg <= '1';
      else
        state_reg <= state_next;
        case state_next is
          when SHIFT =>
            if tx_cnt < 3 then
              tx_cnt <= tx_cnt + 1;
              data_reg <= data_reg(6 downto 0) & '0';
            else
              tx_cnt <= 0;
            end if;
          when others =>
            tx_cnt <= 0;
        end case;
        if state_next = IDLE and enable_i = '1' then
          data_reg <= data_i;
        end if;
        sclk_reg <= not sclk_reg when state_next = SHIFT else '0';
        cs_reg <= '0' when state_next = SHIFT else '1';
      end if;
    end if;
  end process;

  process(state_reg, enable_i, tx_cnt)
  begin
    state_next <= IDLE;
    case state_reg is
      when IDLE =>
        if enable_i = '1' then
          state_next <= SHIFT;
        end if;
      when SHIFT =>
        if tx_cnt = 3 then
          state_next <= DONE;
        end if;
      when DONE =>
        state_next <= IDLE;
      when others =>
        state_next <= IDLE;
    end case;
  end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

