               status_reg <= x"01";
               nominal_flag <= '1';
            else
               status_reg <= x"00";
               nominal_flag <= '0';
            end if;
         end if;
      end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

