    data_i : in std_logic_vector(7 downto 0)
   );
end entity tx_fifo;

architecture rtl of tx_fifo is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   constant FIFO_DEPTH : natural := 16;
   type fifo_mem_t is array (natural range <>) of std_logic_vector(7 downto 0);
   signal mem : fifo_mem_t(0 to FIFO_DEPTH - 1) := (others => (others => '0'));
   signal wr_ptr : natural range 0 to FIFO_DEPTH - 1 := 0;
   signal rd_ptr : natural range 0 to FIFO_DEPTH - 1 := 0;
   signal cnt : natural range 0 to FIFO_DEPTH := 0;
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   fifo_proc : process (clk, rst)
   begin
      if rst = '1' then
         wr_ptr <= 0;
         rd_ptr <= 0;
         cnt <= 0;
      elsif rising_edge(clk) then
         if enable_i = '1' and cnt < FIFO_DEPTH then
            mem(wr_ptr) <= data_i;
            if wr_ptr = FIFO_DEPTH - 1 then
               wr_ptr <= 0;
            else
               wr_ptr <= wr_ptr + 1;
            end if;
            cnt <= cnt + 1;
         end if;
      end if;
   end process fifo_proc;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

