    clk : in std_logic;
    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity tx_fifo;

architecture rtl of tx_fifo is
   constant FIFO_DEPTH : natural := 16;
   type mem_t is array (0 to FIFO_DEPTH - 1) of std_logic_vector(7 downto 0);

   signal mem : mem_t := (others => (others => '0'));
   signal w_ptr : natural := 0;
   signal count : natural := 0;
   signal full : std_logic := '0';
begin
   process(clk)
   begin
      if rising_edge(clk) then
         if rst = '1' then
            w_ptr <= 0;
            count <= 0;
            full <= '0';
         else
            if enable_i = '1' and full = '0' then
               mem(w_ptr) <= data_i;
               if w_ptr = FIFO_DEPTH - 1 then
                  w_ptr <= 0;
               else
                  w_ptr <= w_ptr + 1;
               end if;
               if count = FIFO_DEPTH - 1 then
                  full <= '1';
               else
                  full <= '0';
                  count <= count + 1;
               end if;
            end if;
         end if;
      end if;
   end process;
end architecture rtl;

