    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity uart_rx;

architecture rtl of uart_rx is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   type uart_rx_state_t is (IDLE_ST, START_ST, DATA_ST, STOP_ST);
   signal state_reg : uart_rx_state_t := IDLE_ST;
   signal data_reg  : std_logic_vector(7 downto 0) := (others => '0');
   signal valid_reg : std_logic := '0';
   signal status_reg: std_logic_vector(7 downto 0) := x"00";
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk)
   begin
      if rising_edge(clk) then
         if rst = '1' then
            state_reg  <= IDLE_ST;
            data_reg   <= (others => '0');
            valid_reg  <= '0';
            status_reg <= x"00";
         elsif enable_i = '1' then
            case state_reg is
               when IDLE_ST =>
                  state_reg <= START_ST;
               when START_ST =>
                  state_reg <= DATA_ST;
               when DATA_ST =>
                  data_reg <= data_i;
                  state_reg <= STOP_ST;
               when STOP_ST =>
                  valid_reg <= '1';
                  status_reg <= x"01";
                  state_reg <= IDLE_ST;
               when others =>
                  state_reg <= IDLE_ST;
            end case;
         else
            valid_reg <= '0';
         end if;
      end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

