entity uart_tx is
  port (
    clk : in std_logic;
    rst : in std_logic;
    enable_i : in std_logic;
    data_i : in std_logic_vector(7 downto 0)
   );
end entity uart_tx;

architecture rtl of uart_tx is
   -- MODEL_IMPLEMENTATION_DECLARATIONS_BEGIN
   type uart_state_type is (ST_IDLE, ST_START, ST_DATA, ST_STOP);
   signal state_reg : uart_state_type := ST_IDLE;
   signal data_reg  : std_logic_vector(7 downto 0) := (others => '0');
   signal bit_cnt   : integer range 0 to 8 := 0;
   signal baud_cnt  : integer range 0 to 15 := 0;
   -- MODEL_IMPLEMENTATION_DECLARATIONS_END
begin
   -- MODEL_IMPLEMENTATION_STATEMENTS_BEGIN
   process(clk, rst)
   begin
     if rst = '1' then
       state_reg <= ST_IDLE;
       data_reg  <= (others => '0');
       bit_cnt   <= 0;
       baud_cnt  <= 0;
     elsif rising_edge(clk) then
       if enable_i = '1' and state_reg = ST_IDLE then
         data_reg <= data_i;
         state_reg <= ST_START;
         bit_cnt   <= 0;
       elsif state_reg /= ST_IDLE then
         if baud_cnt = 15 then
           baud_cnt <= 0;
           case state_reg is
             when ST_START =>
               bit_cnt <= 1;
               state_reg <= ST_DATA;
             when ST_DATA =>
               if bit_cnt = 8 then
                 state_reg <= ST_STOP;
                 bit_cnt   <= 0;
               else
                 bit_cnt <= bit_cnt + 1;
               end if;
             when ST_STOP =>
               state_reg <= ST_IDLE;
               bit_cnt   <= 0;
             when others =>
               state_reg <= ST_IDLE;
           end case;
         else
           baud_cnt <= baud_cnt + 1;
         end if;
       end if;
     end if;
   end process;
   -- MODEL_IMPLEMENTATION_STATEMENTS_END
end architecture rtl;

